'use strict';
const ICONS={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',bookmark:'<path d="M6 4a1 1 0 0 1 1-1h10a1 1 0 0 1 1 1v17l-6-4-6 4z"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',github:'<path d="M9 19c-4 1-4-2-6-2m12 4v-3.5a3 3 0 0 0-.9-2.4c3-.3 5.9-1.5 5.9-6.8a5.3 5.3 0 0 0-1.5-3.7A4.8 4.8 0 0 0 18.4 1S17.2.6 14.6 2.4a12.7 12.7 0 0 0-7.2 0C4.8.6 3.6 1 3.6 1a4.8 4.8 0 0 0-.1 3.6A5.3 5.3 0 0 0 2 8.3c0 5.3 2.9 6.5 5.9 6.8a3 3 0 0 0-.9 2.4V21" transform="translate(1 1) scale(.9)"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',spark:'<path d="m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6z"/>',pen:'<path d="m15 4 5 5M4 20l4-1 12-12a3 3 0 0 0-4-4L4 15z"/>',design:'<rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="8" cy="8" r="1"/><path d="m3 17 6-6 4 4 4-5 4 5"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H5l-3 3V10a8 8 0 0 1 8-8h3a8 8 0 0 1 8 9Z"/>',music:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',folder:'<path d="M3 7V4h6l3 3h9v13H3z"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z"/><path d="m8 12 3 3 5-6"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 8V5l14-3v3m4 7h-6v4h6"/>',game:'<path d="M7 7h10c4 0 6 13 2 13l-4-4H9l-4 4C1 20 3 7 7 7zM6 11h5m-2.5-2.5v5M16 11h.1M18 13h.1"/>',box:'<path d="m12 2 10 5v10l-10 5-10-5V7zM2 7l10 5 10-5m-10 5v10"/>'};
function icon(name){return '<svg viewBox="0 0 24 24" aria-hidden="true">'+(ICONS[name]||ICONS.box)+'</svg>';}
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const $=id=>document.getElementById(id);
const REPO='https://github.com/balaji-sivasakthi/awesome-mac-apps';
const palettes=[['#7e71ef','#5142c4'],['#ed9d99','#d37075'],['#72b5ac','#478c8a'],['#8caed5','#5984b4'],['#dfa565','#c68051'],['#8a92d1','#6065a4'],['#ba91c2','#9267a3'],['#7ab5aa','#518f81']];
const specialIcons={'NotchDude':['nd','#45414d','#22212b'],'Raycast':['↗','#ff766e','#e74546'],'Obsidian':['◇','#ac8ae6','#6c44a4'],'Ghostty':['👻','#759cd8','#425d9c'],'IINA':['▶','#94c1df','#5c90c1'],'Maccy':['⌘','#b9bac5','#8c8c9e'],'Alfred':['⌘','#bb8bdd','#7e4dab'],'Homebrew':['♧','#d5ae6b','#ba8d4b'],'Figma':['◉','#eb7978','#c65a69'],'Bitwarden':['▣','#6e9bde','#3c6bb5'],'Keka':['▤','#b29c87','#867462'],'Rectangle':['▥','#aaa6d9','#7872b6']};
const priorities=['NotchDude','Raycast','Obsidian','Ghostty','Maccy','IINA','Alfred','Rectangle','Zed','Bitwarden','Figma','Keka','Homebrew','HandBrake','CotEditor','Visual Studio Code','Blender','Zotero','Joplin','iTerm2'];
const categoryIcons={'Writing & notes':'pen','Developer tools':'code','Design & creative':'design','AI tools':'spark','Communication':'chat','Audio & video':'music','Productivity':'bolt','Files & storage':'folder','Security & privacy':'shield','Browsers':'globe','Finance':'wallet','Games':'game','Utilities':'box','Resources':'grid'};
let apps=[],categories=[],filtered=[],limit=24,toastTimer,searchTimer;
let favorites=new Set();
try{const raw=JSON.parse(localStorage.getItem('awesome-mac-saved')||'[]');if(Array.isArray(raw))favorites=new Set(raw.filter(v=>typeof v==='string'));}catch{}
const query=new URLSearchParams(location.search);
const validFilters=['all','open','free','native','cli'];
const state={q:query.get('q')||'',category:query.get('category')||'',view:query.get('view')==='saved'?'saved':'all',filter:validFilters.includes(query.get('filter'))?query.get('filter'):'all',sort:['az','za'].includes(query.get('sort'))?query.get('sort'):'featured'};
$('search').value=state.q;$('sort').value=state.sort;
function el(tag,className,text){const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;}
function link(label,url,className=''){const a=el('a',className,label);a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2600);}
function appearance(app){if(specialIcons[app.name])return specialIcons[app.name];let sum=0;for(const c of app.name)sum+=c.codePointAt(0);return [app.name.replace(/[^\p{L}\p{N}]/gu,'').slice(0,1).toUpperCase()||'⌘',...palettes[sum%palettes.length]];}
function appIcon(app){const [letter,top,bottom]=appearance(app);const node=el('span','app-icon',letter);node.style.setProperty('--icon-top',top);node.style.setProperty('--icon-bottom',bottom);node.setAttribute('aria-hidden','true');return node;}
function isFree(app){return /free/i.test(app.availability);}
function displayPrice(app){if(app.availability==='See website')return 'Pricing on site';if(app.availability==='Free option')return 'Free option';return app.availability;}
function save(app){if(favorites.has(app.id))favorites.delete(app.id);else favorites.add(app.id);let persisted=true;try{localStorage.setItem('awesome-mac-saved',JSON.stringify([...favorites]));}catch{persisted=false;}const saved=favorites.has(app.id);toast(saved?(persisted?'Saved to your collection':'Saved for this visit'):'Removed from saved apps');if(state.view==='saved')render();else updateSaveButtons();document.querySelectorAll('.saved-count').forEach(e=>e.textContent=favorites.size);}
function updateSaveButtons(){document.querySelectorAll('.save-button').forEach(button=>{const app=apps.find(a=>a.id===button.dataset.id);if(!app)return;const saved=favorites.has(app.id);button.classList.toggle('saved',saved);button.setAttribute('aria-pressed',String(saved));button.setAttribute('aria-label',(saved?'Remove ':'Save ')+app.name+(saved?' from saved apps':''));});}
function card(app){const article=el('article','app-card');const top=el('div','card-top');top.append(appIcon(app));const wrap=el('div','card-title-wrap');const title=el('button','app-title',app.name);title.title=app.name;title.addEventListener('click',()=>showDetail(app));wrap.append(title,el('span','app-category',app.category));top.append(wrap);const saveButton=el('button','save-button');saveButton.innerHTML=icon('bookmark');saveButton.dataset.id=app.id;saveButton.addEventListener('click',()=>save(app));top.append(saveButton);article.append(top,el('p','card-description',app.description));const bottom=el('div','card-bottom'),labels=el('div','card-labels');labels.append(el('span','app-tag'+(isFree(app)?' free':''),displayPrice(app)));if(app.source)labels.append(el('span','app-tag open','Source available'));else if(app.kind!=='App')labels.append(el('span','app-tag',app.kind));bottom.append(labels,link('Website ↗',app.url,'visit-link'));article.append(bottom);return article;}
function updateUrl(){const params=new URLSearchParams();if(state.q)params.set('q',state.q);if(state.category)params.set('category',state.category);if(state.view==='saved')params.set('view','saved');if(state.filter!=='all')params.set('filter',state.filter);if(state.sort!=='featured')params.set('sort',state.sort);history.replaceState(null,'',location.pathname+(params.size?'?'+params:''));}
function applyFilters(){const words=state.q.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);filtered=apps.filter(app=>{if(state.view==='saved'&&!favorites.has(app.id))return false;if(state.category&&app.category!==state.category)return false;if(state.filter==='open'&&!app.source)return false;if(state.filter==='free'&&!isFree(app))return false;if(state.filter==='native'&&!app.native)return false;if(state.filter==='cli'&&app.kind==='App')return false;const text=[app.name,app.description,app.category,...app.categories].join(' ').toLocaleLowerCase();return words.every(w=>text.includes(w));});filtered.sort((a,b)=>{if(state.sort==='za')return b.name.localeCompare(a.name);if(state.sort==='featured'){const ap=priorities.indexOf(a.name),bp=priorities.indexOf(b.name);const rank=(ap<0?999:ap)-(bp<0?999:bp);if(rank)return rank;}return a.name.localeCompare(b.name);});}
function render(){applyFilters();$('app-grid').replaceChildren(...filtered.slice(0,limit).map(card));$('empty-state').hidden=filtered.length!==0;$('load-more').hidden=limit>=filtered.length;$('page-status').textContent=filtered.length?'Showing '+Math.min(limit,filtered.length).toLocaleString()+' of '+filtered.length.toLocaleString()+' apps':'';$('results-meta').textContent=state.q?'Results for “'+state.q+'”':state.view==='saved'?'Your own little collection. Saved in this browser.':state.category?'A few good tools for '+state.category.toLowerCase()+'.':'Thoughtful tools, useful utilities, and a few new favorites.';$('total-count').textContent=filtered.length.toLocaleString()+(filtered.length===1?' app or tool':' apps & tools');$('catalog-title').textContent=state.view==='saved'?'Your saved collection.':state.category?state.category:state.q?'A little closer to your next favorite.':'Discover something awesome.';$('section-eyebrow').textContent=state.view==='saved'?'GOOD FINDS, KEPT CLOSE':'FIND YOUR EVERYDAY ESSENTIALS';$('breadcrumb-title').textContent=state.view==='saved'?'Saved apps':state.category||'Discover';$('hero').hidden=state.view==='saved'||!!state.category||!!state.q;document.querySelectorAll('[data-filter]').forEach(button=>{button.classList.toggle('active',button.dataset.filter===state.filter);button.setAttribute('aria-pressed',String(button.dataset.filter===state.filter));});document.querySelectorAll('.nav-item').forEach(button=>{const active=button.dataset.view==='saved'?state.view==='saved':button.dataset.view==='open'?state.filter==='open'&&state.view!=='saved':state.view==='all'&&state.filter!=='open';button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});document.querySelectorAll('.category-button').forEach(button=>{const active=state.category===button.dataset.category;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});document.querySelectorAll('.saved-count').forEach(e=>e.textContent=favorites.size);updateSaveButtons();updateUrl();}
function change(patch,scroll=false){Object.assign(state,patch);limit=24;$('search').value=state.q;$('sort').value=state.sort;render();closeMenu();if(scroll)$('catalog').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
function closeMenu(){$('sidebar').classList.remove('open');$('mobile-overlay').classList.remove('open');$('menu-toggle').setAttribute('aria-expanded','false');}
function showDetail(app){const container=$('detail-content');container.replaceChildren();const header=el('div','detail-header'),titles=el('div');titles.append(el('h2','',app.name),el('p','',app.category+' · '+app.kind));header.append(appIcon(app),titles);container.append(header,el('p','detail-description',app.description));const meta=el('dl','detail-meta');for(const [label,value]of[['Availability',app.availability==='See website'?'Check the official website':app.availability],['Filed under',app.categories.join(' · ')]]){const d=el('div');d.append(el('dt','',label),el('dd','',value));meta.append(d);}container.append(meta);const actions=el('div','detail-actions');actions.append(link('Visit website ↗',app.url,'button button-dark'));if(app.source)actions.append(link('Source code ↗',app.source,'button'));if(app.store)actions.append(link('App Store ↗',app.store,'button'));const saved=el('button','button',favorites.has(app.id)?'Saved ✓':'Save app');saved.addEventListener('click',()=>{save(app);saved.textContent=favorites.has(app.id)?'Saved ✓':'Save app';});actions.append(saved);container.append(actions,el('p','detail-hint','Check the developer’s website for current pricing, system requirements, and installation instructions.'));$('detail-dialog').showModal();}
function initCategories(){const counts=new Map();for(const app of apps)counts.set(app.category,(counts.get(app.category)||0)+1);categories=Object.keys(categoryIcons).filter(c=>counts.has(c));const fragment=document.createDocumentFragment();for(const category of categories){const button=el('button','category-button');button.dataset.category=category;button.innerHTML=icon(categoryIcons[category]);button.append(el('span','',category),el('span','category-count',counts.get(category).toLocaleString()));button.addEventListener('click',()=>change({category:state.category===category?'':category,view:'all'},true));fragment.append(button);}$('categories').replaceChildren(fragment);$('submit-category').replaceChildren(...categories.filter(c=>c!=='Resources').map(category=>{const option=el('option','',category);option.value=category;return option;}));}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>change({filter:button.dataset.filter})));
document.querySelectorAll('.nav-item').forEach(button=>button.addEventListener('click',()=>{const view=button.dataset.view;change({view:view==='saved'?'saved':'all',filter:view==='open'?'open':'all',category:'',q:''},view==='saved');}));
$('search').addEventListener('input',event=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>change({q:event.target.value}),120);});
$('sort').addEventListener('change',event=>change({sort:event.target.value}));
$('load-more').addEventListener('click',()=>{limit+=24;render();});
$('clear-filters').addEventListener('click',()=>change({q:'',category:'',filter:'all',view:'all'}));
$('feature-open').addEventListener('click',()=>{const app=apps.find(app=>app.name==='NotchDude');if(app)showDetail(app);});
document.querySelectorAll('[data-submit]').forEach(button=>button.addEventListener('click',()=>{closeMenu();$('submit-dialog').showModal();}));
document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}}));
$('about-open').addEventListener('click',()=>$('about-dialog').showModal());
$('menu-toggle').addEventListener('click',()=>{const open=$('sidebar').classList.toggle('open');$('mobile-overlay').classList.toggle('open',open);$('menu-toggle').setAttribute('aria-expanded',String(open));});
$('mobile-overlay').addEventListener('click',closeMenu);
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!document.querySelector('dialog[open]')){event.preventDefault();$('search').focus();}});
$('submit-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.target);const body=['## App name',data.get('app'),'','## Official website',data.get('website'),'','## Purpose',data.get('description'),'','## Category',data.get('category'),'','## Pricing model',data.get('pricing'),'','## Affiliation',data.get('affiliation'),'','## Compatibility and installation',data.get('compatibility'),'','## Source code',data.get('source')||'Not provided','','Please include installation instructions and the source-code license (if applicable) before submitting.'].join('\n');const url=new URL(REPO+'/issues/new');url.searchParams.set('title','Add: '+data.get('app'));url.searchParams.set('body',body);window.open(url.href,'_blank','noopener,noreferrer');toast('Review your details on GitHub before submitting.');});
async function start(){try{const response=await fetch('catalog.json');if(!response.ok)throw new Error('Catalog unavailable');const catalog=await response.json();if(!Array.isArray(catalog.apps))throw new Error('Invalid catalog');apps=catalog.apps.filter(app=>/^https?:\/\//.test(app.url));favorites=new Set([...favorites].filter(id=>apps.some(app=>app.id===id)));$('nav-count').textContent=apps.length.toLocaleString();$('hero-count').textContent=apps.length.toLocaleString();initCategories();if(!categories.includes(state.category))state.category='';render();}catch(error){$('app-grid').replaceChildren();const box=el('div','loading-message');box.append(el('p','','The app collection couldn’t load. Please try again.'));const retry=el('button','button button-dark','Try again');retry.addEventListener('click',start);box.append(retry);$('app-grid').append(box);$('total-count').textContent='Temporarily unavailable';}}
start();
